import React, { FormEvent } from 'react';

import { selectHikerAsync } from '@components/HikerSelector/hikerSelectHelper';
import { getInputDate, getSQLDate } from '@helpers/dateHelper';
import notificationHelper from '@helpers/notificationHelper';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohInput, { InputTypes } from '@ui-kit/Input';

import nophoto from '../../../../../img/nophoto.png';
import { addHikingRepairKitUsages } from '../../../@services/hikingRepairKit.service';
import { IHikingRepairKitUsageCreateDTO } from '../../../@types/DTO/hikingRepairKit.dto.types';
import { IHikingData } from '../../../@types/hiking.types';
import { IHikingRepairKitUsage } from '../../../@types/hikingRepairKit.types';

interface IHikingRepairKitUsageModalProps {
  hikingData: IHikingData;
  repairKitUsage: IHikingRepairKitUsage;
  onChange: (rk: IHikingRepairKitUsage) => void;
}

const HikingRepairKitUsageModal: React.FC<IHikingRepairKitUsageModalProps> = ({
  repairKitUsage,
  hikingData,
  onChange,
}) => {
  const [data, setData] = React.useState<IHikingRepairKitUsage>(repairKitUsage);
  const [isLoading, setIsLoading] = React.useState(false);

  type T = Omit<IHikingRepairKitUsage, 'id' | 'id_hiking_repair_kit'>;

  const handleInputChange =
    <K extends keyof T>(field: keyof T) =>
    async (value: T[K]) => {
      setData((cur) => ({ ...cur, [field]: value }));
    };

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    try {
      setIsLoading(true);
      const dataForSave: IHikingRepairKitUsageCreateDTO = {
        id_hiking_repair_kit: data.id_hiking_repair_kit,
        id_hiking: hikingData.id,
        date: getSQLDate(data.date),
        comment: data.comment,
        id_user: data.user ? data.user.id : null,
      };

      const newId = await addHikingRepairKitUsages(dataForSave);
      onChange({ ...data, id: newId });
      notificationHelper.success('Добавлено');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} style={{ minWidth: 360 }}>
      <PohInput
        type={InputTypes.datetimeLocal}
        label="Дата"
        required
        min={getInputDate(hikingData.start)}
        max={getInputDate(hikingData.finish)}
        value={getInputDate(data.date, false)}
        onChange={(v) => handleInputChange<'date'>('date')(new Date(v))}
        disabled={isLoading}
        wrapperClassName="mb-2"
      />
      <PohInput
        type={InputTypes.textarea}
        label="Комментарий"
        required
        placeholder="Для чего было использовано"
        name="hiking-repair-kit-comment"
        id="hiking-repair-kit-comment"
        value={data.comment}
        onChange={handleInputChange<'comment'>('comment')}
        disabled={isLoading}
        wrapperClassName="mb-2"
      />

      <PohInput
        label="Участник"
        placeholder="Можно не указывать"
        value={data.user ? [data.user.name, data.user.surname].join(' ') : ''}
        readOnly={!!data.user}
        disabled={isLoading}
        style={{
          backgroundImage: `url("${data.user ? data.user.photo : nophoto}")`,
          backgroundSize: '36px',
          paddingLeft: '46px',
          backgroundRepeat: 'no-repeat',
        }}
        onClick={() =>
          selectHikerAsync(hikingData.id, { withMe: true }).then((user) => {
            handleInputChange<'user'>('user')({
              id: user.idUser,
              name: user.name,
              surname: user.surname,
              photo: user.photo['50'],
            });
          })
        }
      />

      <footer className="pt-3 text-end">
        <PohButton
          variant={ButtonVariant.Primary}
          size={ButtonSize.Small}
          type="submit"
          disabled={isLoading}
        >
          {data.id ? 'Сохранить' : 'Добавить'}
        </PohButton>
      </footer>
    </form>
  );
};

export default HikingRepairKitUsageModal;
